// Heavy Pockets Co. coming-soon page, as a Cloudflare Worker.
//
// In plain terms: Cloudflare runs this little program for every visit to
// heavypocketsco.com. It hands back the page and its images, and when someone
// taps "Get first dibs" it saves their email in a Cloudflare KV list named DIBS
// (one entry per email). Nothing here is secret, and no list data is in the repo.
//
// site.js is generated by scripts/build_coming_soon.py (the page plus its images).
import { PAGE, FILES } from './site.js';

const HOST = 'heavypocketsco.com';
const DESIGNS = ['Great Lakes beach stone chart', 'I lick rocks', 'Petoskey socks', 'Agate Expectations', 'Will brake for agates'];
const EMAIL = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

const SECURITY = {
  'content-security-policy': "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; script-src 'self' 'unsafe-inline'; connect-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'",
  'x-content-type-options': 'nosniff',
  'referrer-policy': 'strict-origin-when-cross-origin',
  'permissions-policy': 'camera=(), microphone=(), geolocation=()',
};

const respond = (body, status, type, extra = {}) =>
  new Response(body, { status, headers: { 'content-type': type, ...SECURITY, ...extra } });

const json = (data, status = 200) => respond(JSON.stringify(data), status, 'application/json; charset=utf-8', { 'cache-control': 'no-store' });

// Shown only when someone signs up with scripts turned off (a plain form post).
const plainPage = (title, line) => respond(
  `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${title} | Heavy Pockets Co.</title>` +
  `<style>:root{color-scheme:light dark}body{margin:0;padding:32px 16px;font:18px/1.5 Georgia,serif;background:#0b7a78;color:#fff}main{max-width:36em;margin:0 auto;background:#c4c4c4;color:#111;padding:24px}a{color:#0000d6}` +
  `@media (prefers-color-scheme:dark){body{background:#0b3438}main{background:#2b2d35;color:#ececf1}a{color:#9cc2ff}}</style></head>` +
  `<body><main><h1>${title}</h1><p>${line}</p><p><a href="/">Back to Heavy Pockets Co.</a></p></main></body></html>`,
  200, 'text/html; charset=utf-8', { 'cache-control': 'no-store' });

async function readBody(request) {
  const type = (request.headers.get('content-type') || '').split(';')[0].trim();
  const text = await request.text();
  if (text.length > 4096) return null;
  if (type === 'application/json') { try { return { form: false, data: JSON.parse(text) }; } catch { return null; } }
  if (type === 'application/x-www-form-urlencoded') return { form: true, data: Object.fromEntries(new URLSearchParams(text)) };
  return null;
}

async function dibs(request, env) {
  // Only accept signups sent from this site's own page.
  const origin = request.headers.get('origin');
  let sameSite = true;
  if (origin) { try { sameSite = new URL(origin).host === new URL(request.url).host; } catch { sameSite = false; } }
  if (!sameSite) return json({ ok: false, error: 'Signups only work from heavypocketsco.com.' }, 403);

  const body = await readBody(request);
  if (!body || typeof body.data !== 'object' || body.data === null) return json({ ok: false, error: "That didn't come through. Try again." }, 400);
  const { form, data } = body;

  // The hidden "website" box is a trap for bots. People never see it, so if it's filled, pretend it worked and save nothing.
  if (data.website) return form ? plainPage("You're on the list", "We'll email you when the store opens.") : json({ ok: true });

  const email = String(data.email || '').trim().toLowerCase();
  if (email.length > 254 || !EMAIL.test(email)) {
    const msg = 'That email address looks incomplete. Check it and try again.';
    return form ? plainPage('Check your email address', msg) : json({ ok: false, error: msg }, 400);
  }
  const picks = Array.isArray(data.picks) ? [...new Set(data.picks.filter(p => DESIGNS.includes(p)))] : [];

  const now = new Date().toISOString();
  const old = await env.DIBS.get(email, 'json');
  const keepPicks = picks.length ? picks : (old && old.picks) || [];
  const entry = { email, picks: keepPicks, first: (old && old.first) || now, last: now };
  // Skip the write when nothing changed (the free plan allows 1,000 writes a day).
  if (!old || JSON.stringify(old.picks) !== JSON.stringify(keepPicks)) {
    await env.DIBS.put(email, JSON.stringify(entry), { metadata: { picks: keepPicks, first: entry.first } });
  }
  return form ? plainPage("You're on the list", "We'll email you when the store opens. That's the only email you get unless you ask for more.") : json({ ok: true });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.hostname === 'www.' + HOST) return Response.redirect('https://' + HOST + url.pathname + url.search, 301);

    if (url.pathname === '/api/dibs') {
      if (request.method !== 'POST') return respond('Use POST.', 405, 'text/plain; charset=utf-8', { allow: 'POST' });
      try { return await dibs(request, env); }
      catch (err) { console.error('dibs failed', err && err.message); return json({ ok: false, error: 'Something went wrong on our end. Try again in a minute, or email hello@heavypocketsco.com.' }, 500); }
    }

    if (request.method !== 'GET' && request.method !== 'HEAD') return respond('Not allowed.', 405, 'text/plain; charset=utf-8', { allow: 'GET, HEAD' });

    if (url.pathname === '/' || url.pathname === '/index.html') {
      return respond(request.method === 'HEAD' ? null : PAGE, 200, 'text/html; charset=utf-8', { 'cache-control': 'public, max-age=300' });
    }
    if (url.pathname === '/robots.txt') return respond('User-agent: *\nAllow: /\n', 200, 'text/plain; charset=utf-8');
    if (url.pathname === '/favicon.ico') return Response.redirect(url.origin + '/assets/logo/favicon-32.png', 301);

    const file = FILES[url.pathname];
    if (file) return respond(request.method === 'HEAD' ? null : file.bytes, 200, file.type, { 'cache-control': 'public, max-age=86400' });

    return respond(
      '<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Not found | Heavy Pockets Co.</title>' +
      '<style>:root{color-scheme:light dark}body{font:18px/1.5 Georgia,serif;padding:32px 16px;max-width:36em;margin:0 auto}</style>' +
      '<h1>Nothing on this beach</h1><p>That page doesn\'t exist. <a href="/">Head back to Heavy Pockets Co.</a></p>',
      404, 'text/html; charset=utf-8');
  },
};
